"""Tests for MocapEnvService: locations, the install commands, telling a complete environment apart and the model registry.
Nothing here downloads anything or runs uv."""

import json
import os
import sys

import pytest

from .. import dynamic_import

MocapEnvService = dynamic_import("mpfb.services.mocapenvservice", "MocapEnvService")
_MODULE = sys.modules[MocapEnvService.__module__]


def _write_complete_env(env_dir, spec_version=None):
    """A fake environment: a venv python file and the marker a successful install writes."""
    python = MocapEnvService.get_venv_python(str(env_dir))
    os.makedirs(os.path.dirname(python), exist_ok=True)
    with open(python, "w") as python_file:
        python_file.write("")
    marker = {"spec_version": _MODULE.ENV_SPEC_VERSION if spec_version is None else spec_version}
    with open(os.path.join(str(env_dir), _MODULE.MARKER_FILE), "w") as json_file:
        json.dump(marker, json_file)


def test_service_is_not_instanced():
    with pytest.raises(RuntimeError):
        MocapEnvService()


def test_default_env_dir_is_in_user_home():
    assert MocapEnvService.get_default_env_dir().endswith("mocap_env")


def test_venv_python_is_inside_env():
    python = MocapEnvService.get_venv_python("/some/env")
    assert os.path.normpath(python).startswith(os.path.normpath("/some/env/venv"))


def test_empty_env_dir_is_not_installed(tmp_path):
    assert not MocapEnvService.is_env_installed(str(tmp_path))


def test_complete_env_is_installed(tmp_path):
    _write_complete_env(tmp_path)
    assert MocapEnvService.is_env_installed(str(tmp_path))


def test_env_of_older_spec_is_not_installed(tmp_path):
    _write_complete_env(tmp_path, spec_version=_MODULE.ENV_SPEC_VERSION - 1)
    assert not MocapEnvService.is_env_installed(str(tmp_path))


def test_env_without_python_is_not_installed(tmp_path):
    _write_complete_env(tmp_path)
    os.remove(MocapEnvService.get_venv_python(str(tmp_path)))
    assert not MocapEnvService.is_env_installed(str(tmp_path))


def test_install_steps_with_and_without_own_uv():
    with_pip = [key for key, _label in MocapEnvService.build_install_steps(None)]
    with_own = [key for key, _label in MocapEnvService.build_install_steps("/my/uv")]
    assert with_pip[0] == "install_uv"
    assert with_own[0] == "check_uv"
    assert with_pip[1:] == with_own[1:]
    assert with_pip[-1] == "verify"


def test_package_install_uses_venv_and_torch_backend():
    command = MocapEnvService.build_command("install_packages", "/env", "/uv", "/blender/python")[0]
    assert command[0] == "/uv"
    assert MocapEnvService.get_venv_python("/env") in command
    assert command[command.index("--torch-backend") + 1] == "auto"
    assert "opencv-python" not in command  # mediapipe brings opencv-contrib-python, both provide cv2


def test_uv_is_installed_with_blender_python_into_env():
    command = MocapEnvService.build_command("install_uv", "/env", None, "/blender/python")[0]
    assert command[0] == "/blender/python"
    assert command[command.index("--target") + 1] == os.path.join("/env", "uv")


def test_find_uv_in_pip_target_layout(tmp_path):
    name = "uv.exe" if sys.platform.startswith("win") else "uv"
    (tmp_path / "bin").mkdir()
    (tmp_path / "bin" / name).write_text("")
    assert MocapEnvService.find_uv_in_dir(str(tmp_path)) == str(tmp_path / "bin" / name)


def test_uv_environment_is_kept_inside_env_dir(tmp_path):
    env = MocapEnvService.build_uv_environment(str(tmp_path))
    assert env["UV_CACHE_DIR"].startswith(str(tmp_path))
    assert env["UV_PYTHON_INSTALL_DIR"].startswith(str(tmp_path))
    assert "PYTHONHOME" not in env
    assert env["UV_SYSTEM_CERTS"] == "true"  # https inspected by an antivirus or a proxy


def test_registry_lists_models_with_licence_and_checksums():
    models = MocapEnvService.load_models_registry()["models"]
    assert {"body", "hands", "face", "mouth"} <= {model["task"] for model in models}
    for model in models:
        assert model["license"]
        for file_info in model["files"]:
            assert len(file_info["sha256"]) == 64


def test_no_job_is_running_initially():
    assert not MocapEnvService.get_job().is_running
